<script setup>
import {ref,onMounted} from 'vue'
import {request} from './client'
import UsageAdmin from './UsageAdmin.vue'
const data=ref(null),error=ref(''),busy=ref(false),note=ref(''),country=ref({subscription:'',country:'LK',reason:''}),payment=ref({invoice:'',reference:'',amount_minor:0,reason:''})
async function load(){data.value=await request('account_billing','admin_accounts')}
async function run(fn){busy.value=true;error.value='';note.value='';try{await fn();await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function verify(){await run(async()=>{await request('account_billing','verify_country',country.value);note.value='Billing country verified and recorded. Unpaid offers were voided; existing paid invoices are unchanged.'})}
async function settle(){await run(async()=>{await request('account_billing','confirm_bank_payment',payment.value);note.value='Bank settlement recorded. Subscription activated and receipt queued for email.'})}
onMounted(()=>run(load))
</script>
<template><section><h1>Subscriptions & billing</h1><UsageAdmin/><p>Subscription records retain their issued currency. Provider usage invoices appear separately when enabled.</p><p v-if="error" class="error" role="alert">{{error}}</p><p role="status">{{note}}</p><button class="button subtle" :disabled="busy" @click="run(load)">Refresh accounts</button><div v-if="data" class="subscription-admin">
<section class="panel owner-block"><h2>Accounts</h2><p>Showing the 200 most recently updated accounts. Use the record ID for a specific account.</p><div class="owner-table"><table><thead><tr><th>Account</th><th>Role / plan</th><th>Country</th><th>Review</th></tr></thead><tbody><tr v-for="a in data.accounts" :key="a.name"><td>{{a.display_name}}<br><small>{{a.name}}</small></td><td>{{a.role}} · {{a.plan}}</td><td>{{a.billing_country||'Unverified'}}<br>{{a.country_status}}</td><td><button class="text-button" @click="country={subscription:a.name,country:a.requested_country||a.billing_country||'LK',reason:''}">Review {{a.requested_country||'country'}}</button></td></tr></tbody></table></div></section>
<form class="panel owner-block" @submit.prevent="verify"><h2>Verify billing country</h2><p>Confirm reliable billing evidence before approving. Profile country, IP location and language alone are insufficient.</p><div class="owner-fields"><label>Subscription ID<input v-model="country.subscription" required></label><label>Country code · ISO 3166-1 alpha-2<input v-model="country.country" required minlength="2" maxlength="2" placeholder="LK"></label><label>Evidence reviewed<textarea v-model="country.reason" minlength="10" maxlength="1000" required></textarea></label></div><button class="button primary" :disabled="busy">Verify country</button></form>
<section class="panel owner-block"><h2>Unpaid invoices</h2><p v-if="!data.invoices.length">No unpaid subscription invoices.</p><div v-for="b in data.invoices" :key="b.name" class="owner-review"><div><b>{{b.name}}</b><p>{{b.plan}} · {{b.currency}} {{(b.amount_minor/100).toFixed(2)}} · {{b.country}}</p></div><button class="button subtle" @click="payment={invoice:b.name,amount_minor:b.amount_minor,reference:'',reason:''}">Review bank payment</button></div></section>
<form class="panel owner-block" @submit.prevent="settle"><h2>Confirm a received bank payment</h2><p>Only confirm cleared funds in the SISU bank account. This records a real settlement and sends a receipt. Never use this form to test or simulate a payment.</p><div class="owner-fields"><label>Invoice ID<input v-model="payment.invoice" required></label><label>Unique bank reference<input v-model="payment.reference" required maxlength="120"></label><label>Received amount in minor currency units<input v-model.number="payment.amount_minor" type="number" min="1" step="1" required></label><label>Bank settlement evidence<textarea v-model="payment.reason" minlength="10" maxlength="1000" required></textarea></label></div><button class="button primary" :disabled="busy">Confirm verified bank settlement</button></form></div></section></template>
